import React, { useState, useEffect, useRef, useCallback } from 'react';
import { database } from '../services/firebase';
import { ref, onValue, set, remove, onDisconnect, get } from 'firebase/database';
import MeetingRoom from './MeetingRoom';
import { formatUcastnici } from '../utils/slovakPlural';
import { getUserMediaWithFallbackOptions, attachStreamToVideo } from '../utils/webrtcMedia';
import './RoomDetail.css';

/** Firebase RTDB neprijíma undefined v hodnotách – inak set() zlyhá */
function withoutUndefined(obj) {
  return Object.fromEntries(Object.entries(obj).filter(([, v]) => v !== undefined));
}

function RoomDetail({ room, blockName, currentUser, userData, onBack }) {
  /** Kľúč uzla v RTDB – musí byť `id` z Firebase, nie len `number` (môže chýbať po importe) */
  const roomKey = String(room?.id || room?.number || '').trim();

  const [roomData, setRoomData] = useState(room);
  const [isHost, setIsHost] = useState(false);
  const [isInMeeting, setIsInMeeting] = useState(false);
  const [isWaiting, setIsWaiting] = useState(false);
  const [waitingUsers, setWaitingUsers] = useState([]);
  const [showMeeting, setShowMeeting] = useState(false);
  const [isMicEnabled, setIsMicEnabled] = useState(false);
  const [isCameraEnabled, setIsCameraEnabled] = useState(false);
  const [isPreparingPreview, setIsPreparingPreview] = useState(false);
  const previewVideoRef = useRef(null);
  const previewStreamRef = useRef(null);

  // Real-time načítanie miestnosti
  useEffect(() => {
    if (!roomKey) return undefined;
    const roomRef = ref(database, `rooms/${roomKey}`);
    const unsubscribe = onValue(roomRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setRoomData(data);
        const amIHost = data.hostId === currentUser.uid && data.hasActiveMeeting;
        setIsHost(amIHost);
      }
    });
    return () => unsubscribe();
  }, [roomKey, currentUser.uid]);

  useEffect(() => {
    if (!showMeeting) return;
    if (roomData?.hasActiveMeeting) return;

    setShowMeeting(false);
    setIsInMeeting(false);
    setIsHost(false);
  }, [roomData?.hasActiveMeeting, showMeeting]);

  // Real-time načítanie čakajúcich používateľov
  useEffect(() => {
    if (!roomKey) return undefined;
    const waitingRef = ref(database, `waiting/${roomKey}`);
    const unsubscribe = onValue(waitingRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const waitingArray = Object.keys(data).map(key => ({
          id: key,
          ...data[key]
        }));
        setWaitingUsers(waitingArray);
      } else {
        setWaitingUsers([]);
      }
    });
    return () => unsubscribe();
  }, [roomKey]);

  // Keď ťa host prijme - sleduj či si bol prijatý
  useEffect(() => {
    if (!isWaiting || !roomKey) return;

    const admittedRef = ref(database, `admitted/${roomKey}/${currentUser.uid}`);
    const unsubscribe = onValue(admittedRef, (snapshot) => {
      if (snapshot.val() === true) {
        // Bol si prijatý!
        setIsWaiting(false);
        setIsInMeeting(true);
        setShowMeeting(true);
        // Odstráň zo zoznamu prijatých
        remove(admittedRef);
        (async () => {
          try {
            const roomRef = ref(database, `rooms/${roomKey}`);
            const snap = await get(roomRef);
            const existing = snap.val() || {};
            await set(roomRef, {
              ...existing,
              participants: (existing.participants || 0) + 1
            });
          } catch (e) {
            console.error('Chyba pri úprave počtu účastníkov:', e);
          }
        })();
      }
    });
    return () => unsubscribe();
  }, [isWaiting, currentUser.uid, roomKey, roomData.participants]);

  const releasePreviewStream = useCallback(() => {
    if (previewStreamRef.current) {
      previewStreamRef.current.getTracks().forEach((track) => track.stop());
      previewStreamRef.current = null;
    }
  }, []);

  const setupPreview = useCallback(
    async (micEnabled = isMicEnabled, cameraEnabled = isCameraEnabled) => {
      if (isWaiting) return;
      setIsPreparingPreview(true);
      try {
        releasePreviewStream();
        const stream = await getUserMediaWithFallbackOptions({
          audio: micEnabled,
          video: cameraEnabled,
          allowEmpty: true
        });
        stream.getAudioTracks().forEach((track) => {
          track.enabled = micEnabled;
        });
        stream.getVideoTracks().forEach((track) => {
          track.enabled = cameraEnabled;
        });
        previewStreamRef.current = stream;
        attachStreamToVideo(previewVideoRef.current, stream);
      } catch (error) {
        console.error('Chyba pri príprave náhľadu pred vstupom:', error);
        previewStreamRef.current = new MediaStream();
      } finally {
        setIsPreparingPreview(false);
      }
    },
    [isMicEnabled, isCameraEnabled, isWaiting, releasePreviewStream]
  );

  useEffect(() => {
    if (isWaiting) {
      releasePreviewStream();
      return undefined;
    }
    setupPreview(isMicEnabled, isCameraEnabled);
    return () => {
      releasePreviewStream();
    };
  }, [isWaiting, isMicEnabled, isCameraEnabled, setupPreview, releasePreviewStream]);

  const handleStartMeeting = async () => {
    if (!roomKey || !currentUser?.uid) {
      alert('Chýba identifikátor miestnosti alebo nie si prihlásený.');
      return;
    }

    const roomRef = ref(database, `rooms/${roomKey}`);
    const floorNum = Number(room.floor ?? roomData.floor ?? 1);
    const capNum = Number(room.capacity ?? roomData.capacity ?? 10);

    const meetingPayload = withoutUndefined({
      number: room.number || roomKey,
      block: room.block || blockName || roomData.block,
      floor: Number.isFinite(floorNum) ? floorNum : 1,
      capacity: Number.isFinite(capNum) ? capNum : 10,
      hasActiveMeeting: true,
      participants: 1,
      hostId: currentUser.uid,
      hostName: userData?.displayName || 'Host'
    });

    let toWrite = { ...meetingPayload };
    try {
      const snapshot = await get(roomRef);
      const existing = snapshot.val();
      if (existing && typeof existing === 'object' && !Array.isArray(existing)) {
        toWrite = withoutUndefined({ ...existing, ...meetingPayload });
      }
    } catch (readErr) {
      console.warn('Čítanie rooms (voliteľné merge):', readErr);
    }

    try {
      await set(roomRef, toWrite);
    } catch (error) {
      console.error('Chyba pri zápise meetingu:', error);
      const msg = error?.message || String(error);
      const hint =
        msg.includes('permission') || msg.includes('Permission')
          ? ' Skontroluj v Firebase Console → Realtime Database → Rules, či prihlásený používateľ môže zapisovať do rooms/.'
          : '';
      alert(`Nepodarilo sa spustiť meeting: ${msg}${hint}`);
      return;
    }

    setIsHost(true);
    setIsInMeeting(true);
    setShowMeeting(true);

    // onDisconnect vyžaduje živé spojenie s Firebase; pri zlyhaní nesmie zablokovať štart meetingu
    const registerHostDisconnectCleanup = async () => {
      const tasks = [
        () =>
          onDisconnect(ref(database, `rooms/${roomKey}`)).update({
            hasActiveMeeting: false,
            participants: 0,
            hostId: null,
            hostName: null
          }),
        () => onDisconnect(ref(database, `waiting/${roomKey}`)).remove(),
        () => onDisconnect(ref(database, `admitted/${roomKey}`)).remove(),
        () => onDisconnect(ref(database, `webrtc/${roomKey}`)).remove()
      ];
      for (const task of tasks) {
        try {
          await task();
        } catch (e) {
          console.warn('onDisconnect (nepovinné):', e);
        }
      }
    };
    registerHostDisconnectCleanup();
  };

  const handleRequestJoin = async () => {
    try {
      await set(ref(database, `waiting/${roomKey}/${currentUser.uid}`), {
        uid: currentUser.uid,
        displayName: userData?.displayName || 'Používateľ',
        requestedAt: Date.now()
      });
    } catch (error) {
      console.error('Chyba pri žiadosti:', error);
      alert('Nepodarilo sa odoslať žiadosť');
      return;
    }

    setIsWaiting(true);
    releasePreviewStream();

    try {
      await onDisconnect(ref(database, `waiting/${roomKey}/${currentUser.uid}`)).remove();
    } catch (e) {
      console.warn('onDisconnect waiting (nepovinné):', e);
    }
  };

  const handleTogglePreviewMic = async () => {
    const next = !isMicEnabled;
    setIsMicEnabled(next);
    await setupPreview(next, isCameraEnabled);
  };

  const handleTogglePreviewCamera = async () => {
    const next = !isCameraEnabled;
    setIsCameraEnabled(next);
    await setupPreview(isMicEnabled, next);
  };

  const handleCancelWaiting = async () => {
    try {
      await remove(ref(database, `waiting/${roomKey}/${currentUser.uid}`));
      setIsWaiting(false);
    } catch (error) {
      console.error('Chyba:', error);
    }
  };

  const handleAdmitUser = async (userId) => {
    try {
      // Označ používateľa ako prijatého
      await set(ref(database, `admitted/${roomKey}/${userId}`), true);
      // Odstráň z waiting listu
      await remove(ref(database, `waiting/${roomKey}/${userId}`));
    } catch (error) {
      console.error('Chyba:', error);
    }
  };

  const handleRejectUser = async (userId) => {
    try {
      await remove(ref(database, `waiting/${roomKey}/${userId}`));
    } catch (error) {
      console.error('Chyba:', error);
    }
  };

  const handleLeaveMeeting = async ({ endMeetingForAll = false } = {}) => {
    setShowMeeting(false);
    setIsInMeeting(false);
    setIsHost(false);

    if (isHost) {
      try {
        const roomRef = ref(database, `rooms/${roomKey}`);
        const snap = await get(roomRef);
        const existing = snap.val() || {};

        if (endMeetingForAll) {
          await set(roomRef, {
            ...existing,
            hasActiveMeeting: false,
            participants: 0,
            hostId: null,
            hostName: null
          });
          await remove(ref(database, `waiting/${roomKey}`));
          await remove(ref(database, `admitted/${roomKey}`));
        } else {
          const participantsSnapshot = await get(ref(database, `webrtc/${roomKey}/participants`));
          const participantsData = participantsSnapshot.val() || {};
          const otherParticipants = Object.entries(participantsData)
            .filter(([participantId]) => participantId !== currentUser.uid)
            .map(([participantId, value]) => ({
              uid: participantId,
              displayName: value?.displayName || 'Používateľ',
              joinedAt: Number(value?.joinedAt || 0)
            }))
            .sort((a, b) => {
              if (a.joinedAt === b.joinedAt) return a.uid.localeCompare(b.uid);
              return a.joinedAt - b.joinedAt;
            });

          const nextHost = otherParticipants[0] || null;
          const nextParticipantsCount = Math.max(0, Number(existing.participants || 1) - 1);

          await set(roomRef, {
            ...existing,
            hasActiveMeeting: nextParticipantsCount > 0,
            participants: nextParticipantsCount,
            hostId: nextHost?.uid || null,
            hostName: nextHost?.displayName || null
          });
        }
      } catch (e) {
        console.error('Chyba pri ukončení meetingu (host):', e);
      }
    } else {
      try {
        const currentParticipants = roomData.participants || 0;
        if (currentParticipants > 0) {
          const roomRef = ref(database, `rooms/${roomKey}`);
          const snap = await get(roomRef);
          const existing = snap.val() || {};
          await set(roomRef, {
            ...existing,
            participants: Math.max(0, (existing.participants || 0) - 1)
          });
        }
      } catch (e) {
        console.error('Chyba pri úprave účastníkov:', e);
      }
      await remove(ref(database, `waiting/${roomKey}/${currentUser.uid}`));
      await remove(ref(database, `admitted/${roomKey}/${currentUser.uid}`));
    }
  };

  if (!roomKey) {
    return (
      <div className="room-detail">
        <div className="detail-header">
          <button className="back-button" type="button" onClick={onBack}>
            ← Späť na miestnosti
          </button>
        </div>
        <p style={{ color: 'white', padding: '20px' }}>
          Chyba: miestnosť nemá platný identifikátor v databáze. Skús znova vybrať miestnosť zo zoznamu.
        </p>
      </div>
    );
  }

  // Zobraz meeting cez celú obrazovku
  if (showMeeting) {
    return (
      <MeetingRoom
        roomNumber={roomKey}
        userData={userData}
        currentUser={currentUser}
        isHost={isHost}
        initialMicOn={isMicEnabled}
        initialCameraOn={isCameraEnabled}
        waitingUsers={waitingUsers}
        onAdmitUser={handleAdmitUser}
        onRejectUser={handleRejectUser}
        onLeave={handleLeaveMeeting}
      />
    );
  }

  return (
    <div className="room-detail">
      <div className="detail-header">
        <button className="back-button" onClick={onBack}>
          ← Späť na miestnosti
        </button>
        <div className="room-title">
          <h2>Miestnosť {roomData.number || roomKey}</h2>
          <span className={`status-indicator ${roomData.hasActiveMeeting ? 'active' : 'inactive'}`}>
            {roomData.hasActiveMeeting ? '🔴 Meeting prebieha' : '🟢 Voľná miestnosť'}
          </span>
        </div>
      </div>

      <div className="detail-content">
        {/* Informácie o miestnosti */}
        <div className="info-card">
          <h3>📋 Informácie</h3>
          <div className="info-grid">
            <div className="info-item">
              <span className="label">Blok:</span>
              <span className="value">Blok {blockName}</span>
            </div>
            <div className="info-item">
              <span className="label">Poschodie:</span>
              <span className="value">{roomData.floor}. poschodie</span>
            </div>
            <div className="info-item">
              <span className="label">Kapacita:</span>
              <span className="value">{roomData.capacity} osôb</span>
            </div>
            <div className="info-item">
              <span className="label">Účastníci:</span>
              <span className="value">{roomData.participants}/{roomData.capacity}</span>
            </div>
            {roomData.hostName && (
              <div className="info-item">
                <span className="label">Host:</span>
                <span className="value">👑 {roomData.hostName}</span>
              </div>
            )}
          </div>
        </div>

        {/* Ovládanie */}
        <div className="video-section">
          {(!roomData.hasActiveMeeting || isWaiting) && (
            <div className={`video-placeholder ${roomData.hasActiveMeeting ? '' : 'video-placeholder-with-preview'}`}>
              {roomData.hasActiveMeeting ? (
              <div className="video-active">
                <div className="video-screen">
                  📹
                  <p>Meeting prebieha</p>
                  <p className="participant-count">👥 {formatUcastnici(roomData.participants)}</p>
                  {roomData.hostName && (
                    <p style={{color: '#ffd700', marginTop: '10px'}}>
                      👑 Host: {roomData.hostName}
                    </p>
                  )}
                </div>
              </div>
              ) : (
              <div className="join-preview-panel join-preview-panel-inactive">
                <div className="join-preview-message">Skontroluj zariadenia pred spustením meetingu</div>
                <div className="join-preview-video-wrap">
                  <video ref={previewVideoRef} className="local-self-video" autoPlay muted playsInline />
                  {!isCameraEnabled && <div className="join-preview-avatar">👤</div>}
                </div>
                <div className="join-preview-controls">
                  <button
                    type="button"
                    className={`preview-toggle ${isCameraEnabled ? 'on' : 'off'}`}
                    onClick={handleTogglePreviewCamera}
                    disabled={isPreparingPreview}
                  >
                    {isCameraEnabled ? '📹 Kamera zapnutá' : '📷 Kamera vypnutá'}
                  </button>
                  <button
                    type="button"
                    className={`preview-toggle ${isMicEnabled ? 'on' : 'off'}`}
                    onClick={handleTogglePreviewMic}
                    disabled={isPreparingPreview}
                  >
                    {isMicEnabled ? '🎤 Mikrofón zapnutý' : '🔇 Mikrofón vypnutý'}
                  </button>
                </div>
              </div>
              )}
            </div>
          )}

          <div className="controls">
            {!roomData.hasActiveMeeting ? (
              <button className="btn-primary" onClick={handleStartMeeting}>
                🎬 Začať meeting
              </button>
            ) : isWaiting ? (
              <div className="waiting-status">
                <p>⏳ Niekto v miestnosti ťa čoskoro pustí dnu.</p>
                <button className="btn-danger" onClick={handleCancelWaiting}>
                  ❌ Zrušiť žiadosť
                </button>
              </div>
            ) : !isInMeeting ? (
              <div className="join-preview-panel">
                <div className="join-preview-message">Priprav sa pred vstupom do meetingu</div>
                <div className="join-preview-video-wrap">
                  <video ref={previewVideoRef} className="local-self-video" autoPlay muted playsInline />
                  {!isCameraEnabled && <div className="join-preview-avatar">👤</div>}
                </div>
                <div className="join-preview-controls">
                  <button
                    type="button"
                    className={`preview-toggle ${isCameraEnabled ? 'on' : 'off'}`}
                    onClick={handleTogglePreviewCamera}
                    disabled={isPreparingPreview}
                  >
                    {isCameraEnabled ? '📹 Kamera zapnutá' : '📷 Kamera vypnutá'}
                  </button>
                  <button
                    type="button"
                    className={`preview-toggle ${isMicEnabled ? 'on' : 'off'}`}
                    onClick={handleTogglePreviewMic}
                    disabled={isPreparingPreview}
                  >
                    {isMicEnabled ? '🎤 Mikrofón zapnutý' : '🔇 Mikrofón vypnutý'}
                  </button>
                </div>
                <button className="btn-primary" onClick={handleRequestJoin} disabled={isPreparingPreview}>
                  🚪 Pripojiť sa
                </button>
              </div>
            ) : null}
          </div>
        </div>

        {/* Admin panel - len pre hosta */}
        {isHost && waitingUsers.length > 0 && (
          <div className="admin-panel">
            <h3>👨‍💼 Čakajú na vstup ({waitingUsers.length})</h3>
            <div className="waiting-list">
              {waitingUsers.map(user => (
                <div key={user.id} className="waiting-user">
                  <div className="user-info">
                    <span className="user-name">👤 {user.displayName}</span>
                  </div>
                  <div className="user-actions">
                    <button
                      className="btn-admit"
                      onClick={() => handleAdmitUser(user.id)}
                    >
                      ✅ Pustiť
                    </button>
                    <button
                      className="btn-reject"
                      onClick={() => handleRejectUser(user.id)}
                    >
                      ❌ Odmietnuť
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default RoomDetail;