import React, { useCallback, useEffect, useRef, useState } from 'react';
import { database, storage } from '../services/firebase';
import { ref, onValue, set, remove, update, get } from 'firebase/database';
import { ref as storageRef, uploadBytes, getDownloadURL, deleteObject } from 'firebase/storage';
import * as pdfjsLib from 'pdfjs-dist/legacy/build/pdf';

const ACCEPTED_MIME_TYPES = {
  'application/pdf': 'pdf',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'pptx',
  'application/vnd.ms-powerpoint': 'ppt'
};

const ACCEPTED_EXTENSIONS = {
  pdf: 'pdf',
  pptx: 'pptx',
  ppt: 'ppt'
};

const STORAGE_FOLDER = {
  pdf: 'presentation_pdfs',
  pptx: 'presentation_pptx',
  ppt: 'presentation_pptx'
};

function detectFileType(file) {
  if (!file) return null;
  if (ACCEPTED_MIME_TYPES[file.type]) return ACCEPTED_MIME_TYPES[file.type];
  const name = (file.name || '').toLowerCase();
  if (name.endsWith('.pdf')) return 'pdf';
  if (name.endsWith('.pptx')) return 'pptx';
  if (name.endsWith('.ppt')) return 'ppt';
  return null;
}

function PresentationPanel({ roomNumber, uid, displayName, isHost, participantRoster }) {
  const basePath = `webrtc/${roomNumber}/presentation`;
  const [pres, setPres] = useState(null);
  const [pdfDoc, setPdfDoc] = useState(null);
  const [viewerUrl, setViewerUrl] = useState('');
  const [localPage, setLocalPage] = useState(1);
  const [followPresenter, setFollowPresenter] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [pdfError, setPdfError] = useState(null);
  const [canvasRenderFailed, setCanvasRenderFailed] = useState(false);
  const [renderedPageUrl, setRenderedPageUrl] = useState('');
  // Pre PPTX testujeme či je URL externe dostupné (Office Online viewer fetchuje
  // súbor zo svojho servera, nie z prehliadača používateľa). Keď nie je dostupné
  // (napr. nesprávne storage rules), ukážeme jasnú nápovedu namiesto Microsoft
  // chybovej obrazovky „Súbor sa nepodarilo nájsť".
  const [pptxUrlReachable, setPptxUrlReachable] = useState(null); // null = unknown, true/false = result
  const viewerPageInitRef = useRef(false);
  const renderTaskRef = useRef(null);

  useEffect(() => {
    const r = ref(database, basePath);
    return onValue(r, (snap) => {
      setPres(snap.val());
    });
  }, [basePath]);

  // Po novej generácii (PDF→PPTX, alebo iné PDF) chceme znovu inicializovať
  // pozíciu prehliadača slidu pre divákov.
  const fileUrl = pres?.pdfUrl || pres?.fileUrl;
  const storagePath = pres?.storagePath;
  // Spätná kompatibilita – staré uložené prezentácie nemajú fileType,
  // ale sú vždy PDF (lebo to bolo jediné podporované).
  const fileType = pres?.fileType || (fileUrl ? 'pdf' : null);
  const isPdf = fileType === 'pdf';
  const isOfficeDoc = fileType === 'pptx' || fileType === 'ppt';

  useEffect(() => {
    viewerPageInitRef.current = false;
  }, [fileUrl]);
  const slideViewers = pres?.slideViewers && typeof pres.slideViewers === 'object' ? pres.slideViewers : {};
  const presenterUid = pres?.presenterUid;
  const isPresenter = Boolean(uid && presenterUid && presenterUid === uid);
  // Host musí vždy vidieť aktívnu prezentáciu, aj keď prezentuje niekto iný.
  const canBrowseSlides = isPresenter || isHost || Boolean(uid && slideViewers[uid]);
  const currentPage = Math.max(1, Number(pres?.currentPage) || 1);
  const totalPages = Math.max(0, Number(pres?.totalPages) || 0);

  // PDF rendering – iba ak je file type PDF. Pre PPTX použijeme Office Online viewer.
  useEffect(() => {
    if (!isPdf || (!fileUrl && !storagePath)) {
      setPdfDoc(null);
      setViewerUrl('');
      setPdfError(null);
      setCanvasRenderFailed(false);
      setRenderedPageUrl('');
      return undefined;
    }
    let cancelled = false;
    setPdfError(null);
    setCanvasRenderFailed(false);
    setRenderedPageUrl('');
    const loadPdf = async () => {
      try {
        const resolvedUrl = fileUrl || (storagePath ? await getDownloadURL(storageRef(storage, storagePath)) : '');
        if (!resolvedUrl) {
          throw new Error('Chýba URL na PDF súbor.');
        }
        if (!cancelled) {
          setViewerUrl(resolvedUrl);
        }

        const task = pdfjsLib.getDocument({ url: resolvedUrl, withCredentials: false, disableWorker: true });

        const pdf = await task.promise;
        if (cancelled) return;
        setPdfDoc(pdf);
      } catch (e) {
        if (!cancelled) {
          console.error(e);
          setPdfError('Nepodarilo sa načítať PDF (skontroluj sieť alebo pravidlá Storage).');
        }
      }
    };
    loadPdf();
    return () => {
      cancelled = true;
      if (renderTaskRef.current) {
        renderTaskRef.current.cancel();
      }
    };
  }, [isPdf, fileUrl, storagePath, basePath]);

  // Pre PPTX si len rozlúskneme finálnu URL na embed (potrebujeme ju aj inde)
  // a navyše overíme, či je URL anonymne dostupné (bez prihlásenia). Office
  // Online viewer fetchuje súbor zo svojich serverov bez Firebase tokenu –
  // ak storage rules vyžadujú auth, viewer dostane 403 a zobrazí
  // „Súbor sa nepodarilo nájsť". Túto situáciu vieme rozpoznať a ukázať
  // používateľovi konkrétnu nápovedu (redeploy rules / nahraj PDF).
  useEffect(() => {
    if (!isOfficeDoc || (!fileUrl && !storagePath)) {
      setPptxUrlReachable(null);
      return undefined;
    }
    let cancelled = false;
    setPptxUrlReachable(null);
    (async () => {
      try {
        const resolvedUrl = fileUrl || (storagePath ? await getDownloadURL(storageRef(storage, storagePath)) : '');
        if (!cancelled && resolvedUrl) setViewerUrl(resolvedUrl);
        if (!resolvedUrl) {
          if (!cancelled) setPptxUrlReachable(false);
          return;
        }
        // HEAD request bez credentials – simulujeme čo robí Office Online server.
        // Firebase Storage tokenized URL by mala vrátiť 200, ak rules majú `allow read: if true`.
        const res = await fetch(resolvedUrl, { method: 'HEAD', credentials: 'omit', mode: 'cors' });
        if (!cancelled) setPptxUrlReachable(res.ok);
      } catch (e) {
        if (!cancelled) {
          console.warn('PPTX URL nedostupné externe:', e);
          setPptxUrlReachable(false);
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [isOfficeDoc, fileUrl, storagePath]);

  useEffect(() => {
    if (!isPresenter || !pdfDoc) return;
    const n = pdfDoc.numPages;
    if (!n) return;
    update(ref(database, basePath), {
      totalPages: n,
      updatedAt: Date.now()
    }).catch((e) => {
      console.warn('Aktualizácia počtu strán:', e);
    });
  }, [isPresenter, pdfDoc, basePath]);

  useEffect(() => {
    if (!pdfDoc) return;
    const max = pdfDoc.numPages || 1;
    const pageFromState = isPresenter ? currentPage : localPage;
    const safePage = Math.min(Math.max(1, pageFromState), max);
    let cancelled = false;

    const renderCurrentPage = async () => {
      try {
        if (renderTaskRef.current) {
          renderTaskRef.current.cancel();
        }
        const page = await pdfDoc.getPage(safePage);
        if (cancelled) return;
        const viewport = page.getViewport({ scale: 1 });
        const targetWidth = Math.min(980, Math.max(360, viewport.width));
        const scale = targetWidth / viewport.width;
        const scaledViewport = page.getViewport({ scale });
        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = Math.floor(scaledViewport.width);
        tempCanvas.height = Math.floor(scaledViewport.height);
        const context = tempCanvas.getContext('2d');
        if (!context) return;
        renderTaskRef.current = page.render({
          canvasContext: context,
          viewport: scaledViewport
        });
        await renderTaskRef.current.promise;
        if (!cancelled) {
          const blob = await new Promise((resolve) => tempCanvas.toBlob(resolve, 'image/png'));
          if (!blob) {
            throw new Error('Konverzia renderu PDF na obrázok zlyhala.');
          }
          const nextUrl = URL.createObjectURL(blob);
          setRenderedPageUrl((prev) => {
            if (prev) {
              URL.revokeObjectURL(prev);
            }
            return nextUrl;
          });
          setCanvasRenderFailed(false);
        }
      } catch (error) {
        if (error?.name !== 'RenderingCancelledException' && !cancelled) {
          console.error(error);
          setCanvasRenderFailed(true);
        }
      }
    };

    renderCurrentPage();
    return () => {
      cancelled = true;
      if (renderTaskRef.current) {
        renderTaskRef.current.cancel();
      }
    };
  }, [pdfDoc, isPresenter, currentPage, localPage]);

  useEffect(() => {
    return () => {
      if (renderedPageUrl) {
        URL.revokeObjectURL(renderedPageUrl);
      }
    };
  }, [renderedPageUrl]);

  useEffect(() => {
    if (canBrowseSlides && !isPresenter && pdfDoc && !viewerPageInitRef.current) {
      viewerPageInitRef.current = true;
      const max = pdfDoc.numPages || 1;
      setLocalPage(Math.min(Math.max(1, currentPage), max));
    }
  }, [canBrowseSlides, isPresenter, pdfDoc, currentPage]);

  useEffect(() => {
    if (canBrowseSlides && followPresenter && !isPresenter && pdfDoc) {
      const max = pdfDoc.numPages || 1;
      setLocalPage(Math.min(Math.max(1, currentPage), max));
    }
  }, [currentPage, followPresenter, canBrowseSlides, isPresenter, pdfDoc]);

  const setPresenterPage = useCallback(
    async (next) => {
      if (!isPresenter) return;
      const max = pdfDoc?.numPages || totalPages || 1;
      const safe = Math.min(Math.max(1, next), max);
      try {
        await update(ref(database, basePath), {
          currentPage: safe,
          updatedAt: Date.now()
        });
      } catch (e) {
        console.error(e);
      }
    },
    [pdfDoc, totalPages, isPresenter, basePath]
  );

  const handleUpload = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file) return;
    const detectedType = detectFileType(file);
    if (!detectedType) {
      alert('Vyber súbor PDF alebo PPTX (PowerPoint).');
      return;
    }
    if (!uid) return;
    setUploading(true);
    try {
      const snap = await get(ref(database, basePath));
      const existing = snap.val() || {};
      const prevPath = existing.storagePath;
      const folder = STORAGE_FOLDER[detectedType] || STORAGE_FOLDER.pdf;
      const ext = ACCEPTED_EXTENSIONS[detectedType] || 'pdf';
      const path = `${folder}/${roomNumber}/${uid}_${Date.now()}.${ext}`;
      const sRef = storageRef(storage, path);
      const contentType =
        detectedType === 'pdf'
          ? 'application/pdf'
          : detectedType === 'pptx'
          ? 'application/vnd.openxmlformats-officedocument.presentationml.presentation'
          : 'application/vnd.ms-powerpoint';
      await uploadBytes(sRef, file, { contentType });
      const url = await getDownloadURL(sRef);
      if (prevPath && prevPath !== path) {
        try {
          await deleteObject(storageRef(storage, prevPath));
        } catch (err) {
          console.warn('Starý súbor sa nepodarilo zmazať:', err);
        }
      }
      // Spätná kompatibilita: necháme aj `pdfUrl` aby starší klient (ak by ostal otvorený) niečo videl.
      // Pre PPTX je `pdfUrl` len signál „je tu nejaká prezentácia", reálne sa zobrazuje cez fileUrl + Office viewer.
      await set(ref(database, basePath), {
        pdfUrl: detectedType === 'pdf' ? url : null,
        fileUrl: url,
        fileType: detectedType,
        fileName: file.name || `prezentacia.${ext}`,
        storagePath: path,
        presenterUid: uid,
        presenterName: displayName || 'Prezentujúci',
        currentPage: 1,
        totalPages: 0,
        updatedAt: Date.now(),
        slideViewers: existing.slideViewers && typeof existing.slideViewers === 'object' ? existing.slideViewers : {}
      });
    } catch (err) {
      console.error(err);
      alert('Nahrávanie zlyhalo. Skontroluj pravidlá Firebase Storage.');
    } finally {
      setUploading(false);
    }
  };

  const handleRemovePresentation = async () => {
    if (!fileUrl) return;
    const ok = window.confirm('Naozaj odstrániť prezentáciu z meetingu?');
    if (!ok) return;
    try {
      if (pres?.storagePath) {
        try {
          await deleteObject(storageRef(storage, pres.storagePath));
        } catch (err) {
          console.warn('Zmazanie súboru:', err);
        }
      }
      await remove(ref(database, basePath));
    } catch (err) {
      console.error(err);
      alert('Nepodarilo sa odstrániť prezentáciu.');
    }
  };

  const toggleSlideViewer = async (targetUid) => {
    if (!isHost || !targetUid) return;
    const path = `${basePath}/slideViewers/${targetUid}`;
    const snap = await get(ref(database, path));
    try {
      if (snap.exists()) {
        await remove(ref(database, path));
      } else {
        await set(ref(database, path), true);
      }
    } catch (e) {
      console.error(e);
    }
  };

  const maxKnownPage = pdfDoc?.numPages || totalPages || 1;
  const viewerPage = Math.min(Math.max(1, isPresenter ? currentPage : localPage), maxKnownPage);
  const effectiveTotal = pdfDoc?.numPages || totalPages || 0;
  // Prefer signed download URL pre dlhé inline embedy.
  const popupBaseUrl = fileUrl || viewerUrl;
  const popupHref = popupBaseUrl
    ? isPdf
      ? `${popupBaseUrl}#page=${viewerPage}&zoom=page-fit&toolbar=1&navpanes=0`
      : popupBaseUrl
    : '';
  // Office Online embed pre PPTX/PPT. Vyžaduje verejne dostupnú URL –
  // Firebase Storage tokenized URL z `getDownloadURL` to spĺňa, ak má
  // priečinok `presentation_pptx` v storage.rules `allow read: if true;`.
  const officeEmbedHref = isOfficeDoc && popupBaseUrl
    ? `https://view.officeapps.live.com/op/embed.aspx?src=${encodeURIComponent(popupBaseUrl)}`
    : '';
  const isShowingFallbackPreview = isPdf && (!pdfDoc || canvasRenderFailed) && Boolean(popupHref);
  const openInNewTab = () => {
    if (isOfficeDoc && officeEmbedHref) {
      window.open(officeEmbedHref, '_blank', 'noopener,noreferrer');
      return;
    }
    if (popupHref) {
      window.open(popupHref, '_blank', 'noopener,noreferrer');
    }
  };
  const openRawFile = () => {
    if (popupBaseUrl) window.open(popupBaseUrl, '_blank', 'noopener,noreferrer');
  };

  useEffect(() => {
    setCanvasRenderFailed(false);
  }, [viewerPage]);

  const titleEmoji = isOfficeDoc ? '🖼️' : '📑';
  const titleText = isOfficeDoc ? 'Prezentácia (PowerPoint)' : 'Prezentácia (PDF)';

  return (
    <div className="presentation-panel">
      <h3 className="presentation-title">{titleEmoji} {titleText}</h3>
      <p className="presentation-hint">
        Pri zdieľaní obrazovky ostatní vidia len video. Ak chcete komisii alebo vybraným ľuďom umožniť
        listovať slidy dopredu/dozadu, nahrajte <strong>PDF</strong> (synchronizácia stránok medzi
        prezentérom a divákmi). Podporujeme aj <strong>PPTX</strong> (PowerPoint), ale na bezproblémový
        zážitok odporúčame v PowerPointe použiť <em>Súbor → Export → Vytvoriť PDF</em> a nahrať PDF.
      </p>

      <div className="presentation-toolbar">
        <label className="presentation-upload-label">
          <input
            type="file"
            accept="application/pdf,.pdf,application/vnd.openxmlformats-officedocument.presentationml.presentation,.pptx,application/vnd.ms-powerpoint,.ppt"
            onChange={handleUpload}
            disabled={uploading || !uid}
            className="presentation-file-input"
          />
          <span className="presentation-upload-btn">
            {uploading ? '⏳ Nahrávam…' : '📤 Nahrať PDF / PPTX'}
          </span>
        </label>
        {fileUrl && (isPresenter || isHost) && (
          <button type="button" className="presentation-remove-btn" onClick={handleRemovePresentation}>
            🗑️ Odstrániť prezentáciu
          </button>
        )}
      </div>

      {isHost && participantRoster.length > 0 && (
        <div className="presentation-host-acl">
          <h4>Host – práva na listovanie slidov</h4>
          <p className="presentation-acl-hint">
            Zaškrtni účastníkov, ktorí môžu samostatne listovať celú prezentáciu (dopredu/dozadu).
          </p>
          <ul className="presentation-acl-list">
            {participantRoster
              .filter((p) => p.uid !== presenterUid)
              .map((p) => (
              <li key={p.uid}>
                <label className="presentation-acl-item">
                  <input
                    type="checkbox"
                    checked={Boolean(slideViewers[p.uid])}
                    onChange={() => toggleSlideViewer(p.uid)}
                  />
                  <span>{p.displayName || p.uid}</span>
                  {p.uid === uid ? <span className="presentation-you"> (ty)</span> : null}
                </label>
              </li>
              ))}
          </ul>
        </div>
      )}

      {!fileUrl && <p className="presentation-empty">Zatiaľ nie je nahraté žiadne PDF ani PPTX.</p>}

      {fileUrl && (
        <div className="presentation-active">
          <div className="presentation-meta">
            <span>
              Prezentujúci: <strong>{pres?.presenterName || '—'}</strong>
            </span>
            <span className="presentation-slide-count">
              {isPdf
                ? `Stránka ${viewerPage}${effectiveTotal > 0 ? ` / ${effectiveTotal}` : ''}${
                    isPresenter ? ' (tvoja pozícia sa zdieľa s miestnosťou)' : ''
                  }`
                : `${pres?.fileName || 'PowerPoint prezentácia'} (každý si listuje sám)`}
            </span>
          </div>

          {canBrowseSlides ? (
            <div className="presentation-viewer">
              {isPdf && !isPresenter && (
                <div className="presentation-follow-row">
                  <label className="presentation-follow-label">
                    <input
                      type="checkbox"
                      checked={followPresenter}
                      onChange={(e) => setFollowPresenter(e.target.checked)}
                    />
                    Sledovať pozíciu prezentéra
                  </label>
                  <button
                    type="button"
                    className="control-btn on"
                    onClick={() => {
                      setFollowPresenter(true);
                      const max = pdfDoc?.numPages || effectiveTotal || 1;
                      setLocalPage(Math.min(Math.max(1, currentPage), max));
                    }}
                  >
                    ↩ Na slide prezentéra
                  </button>
                </div>
              )}

              {isPdf && (
                <div className="presentation-nav">
                  <button
                    type="button"
                    className="control-btn on"
                    disabled={viewerPage <= 1}
                    onClick={() => {
                      if (isPresenter) {
                        setPresenterPage(currentPage - 1);
                      } else {
                        setFollowPresenter(false);
                        setLocalPage((p) => Math.max(1, p - 1));
                      }
                    }}
                  >
                    ← Predchádzajúci
                  </button>
                  <button
                    type="button"
                    className="control-btn on"
                    disabled={effectiveTotal > 0 && viewerPage >= effectiveTotal}
                    onClick={() => {
                      if (isPresenter) {
                        setPresenterPage(currentPage + 1);
                      } else {
                        setFollowPresenter(false);
                        const max = pdfDoc?.numPages || effectiveTotal || 1;
                        setLocalPage((p) => Math.min(max, p + 1));
                      }
                    }}
                  >
                    Ďalší →
                  </button>
                  <button
                    type="button"
                    className="control-btn on"
                    disabled={!popupHref}
                    onClick={openInNewTab}
                  >
                    🔎 Otvoriť v novom okne
                  </button>
                </div>
              )}

              {isOfficeDoc && (
                <div className="presentation-nav">
                  <button
                    type="button"
                    className="control-btn on"
                    disabled={!officeEmbedHref}
                    onClick={openInNewTab}
                  >
                    🔎 Otvoriť v novom okne
                  </button>
                </div>
              )}

              <div className="presentation-canvas-wrap">
                {isPdf && pdfError && !isShowingFallbackPreview && (
                  <p className="presentation-error">{pdfError}</p>
                )}
                {isPdf && pdfDoc && !canvasRenderFailed && renderedPageUrl && (
                  <img
                    src={renderedPageUrl}
                    alt={`PDF strana ${viewerPage}`}
                    className="presentation-canvas"
                  />
                )}
                {isPdf && isShowingFallbackPreview && (
                  <div className="presentation-inline-fallback">
                    <p className="presentation-inline-hint">
                      Použitý záložný PDF náhľad.
                    </p>
                    <iframe
                      key={`pdf-inline-${viewerPage}`}
                      title="PDF inline preview"
                      src={popupHref}
                      className="presentation-iframe"
                    />
                  </div>
                )}
                {isOfficeDoc && officeEmbedHref && pptxUrlReachable !== false && (
                  <div className="presentation-inline-fallback">
                    <p className="presentation-inline-hint">
                      Náhľad PowerPoint prezentácie. Načítanie môže trvať pár sekúnd.
                    </p>
                    <iframe
                      key={`pptx-inline-${pres?.updatedAt || 'live'}`}
                      title="PowerPoint inline preview"
                      src={officeEmbedHref}
                      className="presentation-iframe"
                      allow="fullscreen"
                    />
                  </div>
                )}
                {isOfficeDoc && pptxUrlReachable === false && (
                  // Storage rules nedovoľujú anonymné čítanie → Office viewer
                  // by zobrazil len chybu „Súbor sa nepodarilo nájsť". Namiesto
                  // toho ukážeme jasnú nápovedu so 100% spoľahlivým riešením.
                  <div className="presentation-pptx-blocked">
                    <h4>📎 Súbor je nahraný, ale Office Online ho nemôže načítať</h4>
                    <p>
                      Online náhľad PowerPoint vyžaduje, aby Microsoft mohol súbor
                      stiahnuť zo svojich serverov. Pravidlá tvojho Firebase Storage
                      momentálne nepúšťajú anonymné čítanie pre <code>presentation_pptx/</code>.
                    </p>
                    <p>
                      <strong>Najjednoduchšie riešenie (odporúčané):</strong> v PowerPointe daj
                      <em> Súbor → Export → Vytvoriť PDF/XPS</em> a nahraj PDF –
                      tak budeš mať aj <strong>synchronizáciu stránok medzi prezentérom a divákmi</strong>.
                    </p>
                    <p>
                      <strong>Alternatíva:</strong> v <code>storage.rules</code> nastav pre
                      cestu <code>/presentation_pptx/{`{roomId}/{fileName}`}</code> pravidlo
                      <code> allow read: if true;</code> a redeployni cez
                      <code> npx firebase-tools deploy --only storage</code>.
                    </p>
                    <div className="presentation-pptx-blocked-actions">
                      <button type="button" className="control-btn on" onClick={openInNewTab}>
                        🔎 Skúsiť otvoriť cez Office Online
                      </button>
                      <button type="button" className="control-btn" onClick={openRawFile}>
                        💾 Stiahnuť súbor priamo
                      </button>
                    </div>
                  </div>
                )}
                {isPdf && !popupHref && !renderedPageUrl && (
                  <p className="presentation-error">Náhľad sa nepodarilo zobraziť inline. Použi otvorenie v novom okne.</p>
                )}
              </div>
            </div>
          ) : (
            <p className="presentation-no-access">
              Prezentácia je aktívna. Na samostatné listovanie slidov potrebuješ práva od hosta.
            </p>
          )}
        </div>
      )}
    </div>
  );
}

export default PresentationPanel;
