import React, { useState, useEffect } from 'react';
import { database } from '../services/firebase';
import { ref, onValue } from 'firebase/database';
import packageJson from '../../package.json';

/** Slovenské skloňovanie počtu aktívnych meetingov v bloku */
function formatActiveMeetingsPhrase(count) {
  if (count === 0) {
    return '⚪ Žiadne aktívne meetingy';
  }
  if (count >= 1 && count <= 4) {
    return `🔴 ${count} aktívne meetingy`;
  }
  return `🔴 ${count} aktívnych meetingov`;
}

function BlockList({ onBlockSelect }) {
  const [blocks, setBlocks] = useState([]);
  const [roomsByBlock, setRoomsByBlock] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const blocksRef = ref(database, 'blocks');

    const unsubscribe = onValue(blocksRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        const blocksArray = Object.keys(data).map((key) => ({
          id: key,
          name: key,
          ...data[key]
        }));
        setBlocks(blocksArray);
      } else {
        setBlocks([]);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const roomsRef = ref(database, 'rooms');

    const unsubscribe = onValue(roomsRef, (snapshot) => {
      const data = snapshot.val();
      const counts = {};
      if (data) {
        Object.values(data).forEach((room) => {
          if (!room || !room.block) return;
          if (!counts[room.block]) counts[room.block] = { active: 0 };
          if (room.hasActiveMeeting) {
            counts[room.block].active += 1;
          }
        });
      }
      setRoomsByBlock(counts);
    });

    return () => unsubscribe();
  }, []);

  const activeCountForBlock = (blockName) => roomsByBlock[blockName]?.active ?? 0;
  const buildLabel = process.env.REACT_APP_BUILD_LABEL || `v${packageJson.version}`;

  if (loading) {
    return (
      <div className="block-list">
        <h2>Načítavam bloky...</h2>
      </div>
    );
  }

  return (
    <div className="block-list">
      <h2>Výber blok</h2>
      <div className="blocks-grid">
        {blocks.map(block => (
          <div 
            key={block.id} 
            className="block-card"
            onClick={() => onBlockSelect(block.name)}
          >
            <h3>Blok {block.name}</h3>
            <div className="block-info">
              <p>📍 {block.roomCount} miestností</p>
              <p className={activeCountForBlock(block.name) > 0 ? 'active' : 'inactive'}>
                {formatActiveMeetingsPhrase(activeCountForBlock(block.name))}
              </p>
            </div>
          </div>
        ))}
      </div>
      <div className="deploy-version-badge" title="Verzia nasadenej aplikácie">
        {buildLabel}
      </div>
    </div>
  );
}

export default BlockList;